class Solution:
    def minOperationsPeaks(self, nums, k):
        n = len(nums)
        if k > n // 2:
            return -1
        if k == 0:
            return 0
        cost = [max(0, max(nums[i - 1], nums[(i + 1) % n]) + 1 - nums[i]) for i in range(n)]
        INF = float('inf')
        def solve(first_peak):
            dp = [[INF] * (k + 1) for _ in range(2)]
            if first_peak:
                dp[1][1] = cost[0]
            else:
                dp[0][0] = 0
            for i in range(1, n):
                nd = [[INF] * (k + 1) for _ in range(2)]
                for p in range(2):
                    for c in range(k + 1):
                        v = dp[p][c]
                        if v == INF:
                            continue
                        if nd[0][c] > v:
                            nd[0][c] = v
                        if not p and c < k and nd[1][c + 1] > v + cost[i]:
                            nd[1][c + 1] = v + cost[i]
                dp = nd
            best = INF
            for p in range(2):
                if first_peak and p:
                    continue
                best = min(best, dp[p][k])
            return best
        return min(solve(True), solve(False))

