class Solution {
public:
    int minOperationsPeaks(vector<int>& nums, int k) {
        int n = nums.size();
        if (k > n / 2) return -1;
        if (k == 0) return 0;
        vector<long long> cost(n);
        for (int i = 0; i < n; i++) {
            int a = nums[(i - 1 + n) % n], b = nums[(i + 1) % n];
            cost[i] = max(0, max(a, b) + 1 - nums[i]);
        }
        const long long INF = LLONG_MAX / 2;
        auto solve = [&](bool firstPeak) {
            vector<array<long long, 5001>> dp(2);
            int K = k;
            vector<vector<long long>> d(2, vector<long long>(K + 1, INF));
            if (firstPeak) d[1][1] = cost[0];
            else d[0][0] = 0;
            for (int i = 1; i < n; i++) {
                vector<vector<long long>> nd(2, vector<long long>(K + 1, INF));
                for (int p = 0; p < 2; p++)
                    for (int c = 0; c <= K; c++) {
                        long long v = d[p][c];
                        if (v >= INF) continue;
                        nd[0][c] = min(nd[0][c], v);
                        if (!p && c < K) nd[1][c + 1] = min(nd[1][c + 1], v + cost[i]);
                    }
                d = move(nd);
            }
            long long best = INF;
            for (int p = 0; p < 2; p++) {
                if (firstPeak && p) continue;
                best = min(best, d[p][K]);
            }
            return best;
        };
        return (int) min(solve(true), solve(false));
    }
};

