class Solution {
    public int minOperationsPeaks(int[] nums, int k) {
        int n = nums.length;
        if (k > n / 2) return -1;
        if (k == 0) return 0;
        long[] cost = new long[n];
        for (int i = 0; i < n; i++) {
            int a = nums[(i - 1 + n) % n], b = nums[(i + 1) % n];
            cost[i] = Math.max(0, Math.max(a, b) + 1 - nums[i]);
        }
        final long INF = Long.MAX_VALUE / 2;
        java.util.function.LongSupplier[] sol = new java.util.function.LongSupplier[2];
        for (int fp = 0; fp < 2; fp++) {
            final boolean firstPeak = fp == 1;
            sol[fp] = () -> {
                long[][] d = new long[2][k + 1];
                for (long[] row : d) java.util.Arrays.fill(row, INF);
                if (firstPeak) d[1][1] = cost[0];
                else d[0][0] = 0;
                for (int i = 1; i < n; i++) {
                    long[][] nd = new long[2][k + 1];
                    for (long[] row : nd) java.util.Arrays.fill(row, INF);
                    for (int p = 0; p < 2; p++)
                        for (int c = 0; c <= k; c++) {
                            long v = d[p][c];
                            if (v >= INF) continue;
                            nd[0][c] = Math.min(nd[0][c], v);
                            if (p == 0 && c < k) nd[1][c + 1] = Math.min(nd[1][c + 1], v + cost[i]);
                        }
                    d = nd;
                }
                long best = INF;
                for (int p = 0; p < 2; p++) {
                    if (firstPeak && p == 1) continue;
                    best = Math.min(best, d[p][k]);
                }
                return best;
            };
        }
        return (int) Math.min(sol[0].getAsLong(), sol[1].getAsLong());
    }
}

