var minOperationsPeaks = function(nums, k) {
    const n = nums.length;
    if (k > Math.floor(n / 2)) return -1;
    if (k === 0) return 0;
    const cost = nums.map((_, i) =>
        Math.max(0, Math.max(nums[(i - 1 + n) % n], nums[(i + 1) % n]) + 1 - nums[i]));
    const INF = Infinity;
    const solve = firstPeak => {
        let d = [new Array(k + 1).fill(INF), new Array(k + 1).fill(INF)];
        if (firstPeak) d[1][1] = cost[0];
        else d[0][0] = 0;
        for (let i = 1; i < n; i++) {
            const nd = [new Array(k + 1).fill(INF), new Array(k + 1).fill(INF)];
            for (let p = 0; p < 2; p++)
                for (let c = 0; c <= k; c++) {
                    const v = d[p][c];
                    if (v === INF) continue;
                    if (nd[0][c] > v) nd[0][c] = v;
                    if (!p && c < k && nd[1][c + 1] > v + cost[i]) nd[1][c + 1] = v + cost[i];
                }
            d = nd;
        }
        let best = INF;
        for (let p = 0; p < 2; p++) {
            if (firstPeak && p) continue;
            best = Math.min(best, d[p][k]);
        }
        return best;
    };
    return Math.min(solve(true), solve(false));
};

